'use client';

import { Tabs as TabsPrimitive, useTabs, useTabsContext } from '@ark-ui/react/tabs';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef } from 'react';
import { forwardRef } from 'react';
import styles from './Tabs.module.css';

type TabsVariant = 'default' | 'line';
type TabsSize = 'sm' | 'md' | 'lg';
type TabsStyleProps = { variant?: TabsVariant; size?: TabsSize; fitted?: boolean };
type TabsRootProps = ComponentProps<typeof TabsPrimitive.Root> & TabsStyleProps;
type TabsRootProviderProps = ComponentProps<typeof TabsPrimitive.RootProvider> & TabsStyleProps;

const Tabs = forwardRef<ComponentRef<typeof TabsPrimitive.Root>, TabsRootProps>(function Tabs(
  { className, variant = 'default', size = 'md', fitted = false, ...props },
  ref,
) {
  return (
    <TabsPrimitive.Root
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-variant={variant}
      data-size={size}
      data-fitted={fitted ? '' : undefined}
      data-slot="tabs-root"
    />
  );
});

const TabsRootProvider = forwardRef<
  ComponentRef<typeof TabsPrimitive.RootProvider>,
  TabsRootProviderProps
>(function TabsRootProvider(
  { className, variant = 'default', size = 'md', fitted = false, ...props },
  ref,
) {
  return (
    <TabsPrimitive.RootProvider
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-variant={variant}
      data-size={size}
      data-fitted={fitted ? '' : undefined}
      data-slot="tabs-root-provider"
    />
  );
});

const TabsList = forwardRef<
  ComponentRef<typeof TabsPrimitive.List>,
  ComponentProps<typeof TabsPrimitive.List>
>(function TabsList({ className, ...props }, ref) {
  return (
    <TabsPrimitive.List
      ref={ref}
      className={clsx(styles.list, className)}
      {...props}
      data-slot="tabs-list"
    />
  );
});

const TabsTrigger = forwardRef<
  ComponentRef<typeof TabsPrimitive.Trigger>,
  ComponentProps<typeof TabsPrimitive.Trigger>
>(function TabsTrigger({ className, ...props }, ref) {
  return (
    <TabsPrimitive.Trigger
      ref={ref}
      className={clsx(styles.trigger, className)}
      {...props}
      data-slot="tabs-trigger"
    />
  );
});

const TabsIndicator = forwardRef<
  ComponentRef<typeof TabsPrimitive.Indicator>,
  ComponentProps<typeof TabsPrimitive.Indicator>
>(function TabsIndicator({ className, ...props }, ref) {
  return (
    <TabsPrimitive.Indicator
      ref={ref}
      className={clsx(styles.indicator, className)}
      {...props}
      data-slot="tabs-indicator"
    />
  );
});

const TabsContent = forwardRef<
  ComponentRef<typeof TabsPrimitive.Content>,
  ComponentProps<typeof TabsPrimitive.Content>
>(function TabsContent({ className, ...props }, ref) {
  return (
    <TabsPrimitive.Content
      ref={ref}
      className={clsx(styles.content, className)}
      {...props}
      data-slot="tabs-content"
    />
  );
});

const TabsContext = TabsPrimitive.Context;

export {
  Tabs,
  TabsContext,
  TabsContent,
  TabsIndicator,
  TabsList,
  TabsRootProvider,
  TabsTrigger,
  useTabs,
  useTabsContext,
};
export type {
  TabContentProps,
  TabIndicatorProps,
  TabListProps,
  TabsContextProps,
  TabsFocusChangeDetails,
  TabsValueChangeDetails,
  TabTriggerProps,
  UseTabsContext,
  UseTabsProps,
  UseTabsReturn,
} from '@ark-ui/react/tabs';
export type { TabsRootProps, TabsRootProviderProps, TabsSize, TabsVariant };

@layer moduix.components {
  .root {
    --_tabs-size: var(--moduix-size-md);
    --_tabs-trigger-padding-x: var(--moduix-spacing-2-5);
    --_tabs-font-size: var(--moduix-text-sm);
    --_tabs-line-height: var(--moduix-line-height-text-sm);

    box-sizing: border-box;
    display: flex;
    inline-size: 100%;
    min-width: 0;
    flex-direction: column;
    gap: var(--moduix-spacing-3);
    color: var(--moduix-color-foreground);

    &[data-size='sm'] {
      --_tabs-size: var(--moduix-size-sm);
      --_tabs-trigger-padding-x: var(--moduix-spacing-2);
    }

    &[data-size='lg'] {
      --_tabs-size: var(--moduix-size-lg);
      --_tabs-trigger-padding-x: var(--moduix-spacing-3);
      --_tabs-font-size: var(--moduix-text-md);
      --_tabs-line-height: var(--moduix-line-height-text-md);
    }

    &[data-orientation='vertical'] {
      flex-direction: row;
    }
  }

  .list {
    box-sizing: border-box;
    position: relative;
    isolation: isolate;
    display: inline-flex;
    width: fit-content;
    max-width: 100%;
    gap: var(--moduix-spacing-1);
    padding: var(--moduix-spacing-1);
    border: var(--moduix-border-width-sm) solid
      var(--moduix-tabs-list-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-radius-lg);
    background-color: var(--moduix-tabs-list-bg, var(--moduix-color-muted));

    &[data-orientation='horizontal'] {
      overflow-x: auto;
    }

    .root[data-fitted] &[data-orientation='horizontal'] {
      width: 100%;
    }

    &[data-orientation='vertical'] {
      inline-size: min(12rem, 40%);
      flex-direction: column;
    }

    .root[data-variant='line'] & {
      border-width: 0;
      border-radius: 0;
      background-color: transparent;

      &[data-orientation='horizontal'] {
        width: 100%;
        padding-inline: 0;
        border-block-end-width: var(--moduix-border-width-sm);
      }

      &[data-orientation='vertical'] {
        padding-block: 0;
        border-inline-end-width: var(--moduix-border-width-sm);
      }
    }
  }

  .trigger {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--moduix-spacing-2);
    height: calc(
      var(--_tabs-size) - 2 * var(--moduix-spacing-1) - 2 * var(--moduix-border-width-sm)
    );
    margin: 0;
    border: 0;
    border-radius: var(--moduix-radius-md);
    padding-inline: var(--_tabs-trigger-padding-x);
    background: none;
    color: var(--moduix-tabs-tab-color, var(--moduix-color-muted-foreground));
    font: inherit;
    font-size: var(--_tabs-font-size);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--_tabs-line-height);
    text-decoration: none;
    white-space: nowrap;
    user-select: none;
    outline: 0;
    cursor: pointer;
    transition: color var(--moduix-transition-default);

    &[data-selected] {
      color: var(--moduix-tabs-tab-color-active, var(--moduix-color-foreground));
    }

    .root[data-fitted] &[data-orientation='horizontal'] {
      flex: 1;
    }

    @media (hover: hover) {
      &:hover {
        color: var(--moduix-tabs-tab-color-active, var(--moduix-color-foreground));
      }
    }

    &:focus-visible {
      outline: var(--moduix-focus-ring-inset-width) solid var(--moduix-color-ring);
      outline-offset: var(--moduix-focus-ring-inset-offset);
    }

    &[data-disabled] {
      cursor: default;
      opacity: var(--moduix-opacity-disabled);
      pointer-events: none;
    }

    & > svg {
      width: var(--moduix-spacing-4);
      height: var(--moduix-spacing-4);
      flex-shrink: 0;
    }
  }

  .indicator {
    --transition-duration: var(--moduix-duration-normal);
    --transition-timing-function: var(--moduix-ease-in-out);

    z-index: -1;
    top: var(--top);
    left: var(--left);
    width: var(--width);
    height: var(--height);
    border-radius: var(--moduix-radius-md);
    background-color: var(--moduix-tabs-indicator-bg, var(--moduix-color-background));
    box-shadow: var(--moduix-shadow-sm);
    pointer-events: none;

    .root[data-variant='line'] & {
      border-radius: var(--moduix-radius-full);
      background-color: var(--moduix-tabs-tab-color-active, var(--moduix-color-foreground));
      box-shadow: none;

      &[data-orientation='horizontal'] {
        top: auto;
        bottom: 0;
        height: var(--moduix-spacing-0-5);
      }

      &[data-orientation='vertical'] {
        inset-inline-start: auto;
        inset-inline-end: 0;
        width: var(--moduix-spacing-0-5);
      }
    }
  }

  .content {
    box-sizing: border-box;
    flex: 1;
    min-width: 0;
    border: var(--moduix-border-width-sm) solid
      var(--moduix-tabs-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-radius-lg);
    background-color: var(--moduix-tabs-bg, var(--moduix-color-background));
    padding: var(--moduix-spacing-4);
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
    outline: 0;

    &:focus-visible {
      outline: var(--moduix-focus-ring-inset-width) solid var(--moduix-color-ring);
      outline-offset: var(--moduix-focus-ring-inset-offset);
    }
  }
}
